import{r as e,o as n,c as s}from"./index-CmhyUVQL.js";const i=[{id:0,question:"灵山大佛开放时间是几点？",answer:"灵山胜境景区开放时间为 07:30-17:30（夏季可能延长至18:00），灵山大佛区域全天可参观，建议上午前往光线最佳。"},{id:1,question:"景区门票多少钱，有没有优惠？",answer:"成人票210元/人，儿童1.2米以下免票，1.2-1.5米半价；65岁以上老人凭身份证半价；学生凭学生证享8折优惠；团体10人以上可享团体票。"},{id:2,question:"景区停车收费标准是什么？",answer:"小型车辆10元/次（当日有效），大型车辆20元/次；停车场位于景区入口两侧，节假日车位紧张建议早到。"},{id:3,question:"景区游览全程大概需要多久？",answer:"全程步行游览约需4-5小时，乘坐观光车约3小时；建议预留半天时间，重点游览灵山大佛、九龙灌浴、灵山梵宫等核心景点。"},{id:4,question:"景区内有没有素食餐厅？",answer:"景区内设有多处素食餐厅，灵山梵宫内有无自助素斋餐厅，祥符禅寺附近有素面馆；推荐品尝灵山特色素斋，人均50-80元。"},{id:5,question:"带老人小孩游玩路线推荐？",answer:"推荐乘坐观光车游览：入口 → 阿育王柱 → 灵山大佛 → 九龙灌浴 → 灵山梵宫 → 五印坛城，全程约2小时，步行较少，老少皆宜。"},{id:6,question:"景区祈福流程有什么讲究？",answer:"灵山祈福建议顺时针绕佛三圈，双手合十虔诚礼拜；可在祥符禅寺请香祈福，在祈福普缘挂祈福牌；抱佛脚寓意好运，佛手前祈求平安吉祥。"},{id:7,question:"景区周边有什么平价民宿？",answer:"灵山胜境周边有多家平价民宿，价格150-300元/晚不等，建议提前在平台预订；景区入口处的灵山小镇也有精品客栈可选。"},{id:8,question:"景区节假日人流量大吗？",answer:"春节、五一、国庆等重大节假日人流量较大，建议错峰出行或上午9点前入园；平日游览体验更佳，拍照打卡无需排队。"},{id:9,question:"灵山内部观光车怎么收费？",answer:"观光车单程30元/人，通票50元/人（当日不限次数），覆盖景区主要景点；建议购买通票，省力省时，尤其适合带老人小孩的游客。"}],t=[{id:0,question:"这家店人均消费多少？",answer:"人均消费约60-120元，具体根据点菜数量有所不同；招牌菜价格适中，丰俭由人。"},{id:1,question:"需不需要提前电话预约？",answer:"周末及节假日建议提前1-2小时电话预约，平日通常无需预约；大桌聚餐（6人以上）建议提前预订。"},{id:2,question:"特色招牌菜是什么？",answer:"店内招牌菜为灵山特色素斋和太湖三白（白鱼、白虾、银鱼），均选用本地新鲜食材，口味鲜美独特。"},{id:3,question:"营业时间到几点关门？",answer:"营业时间为 10:00-21:00，午餐高峰 11:30-13:00，晚餐高峰 17:30-19:00，建议错峰用餐。"},{id:4,question:"有没有免费停车位？",answer:"店门前有免费停车位约10个，先到先得；对面公共停车场也可停放，前2小时免费。"},{id:5,question:"适合多人聚餐吗？",answer:"店内设有大桌和包间，最多可容纳15人同时就餐；聚餐建议提前预订包间，环境舒适私密。"},{id:6,question:"菜品口味偏淡还是偏浓？",answer:"菜品以苏帮菜为主，口味偏清淡鲜甜，注重食材本味；可根据需求向店家说明调整口味浓淡。"},{id:7,question:"有没有儿童清淡菜品？",answer:"店内有儿童套餐和清淡蒸蛋、小馄饨等适合儿童的菜品，少油少盐，营养均衡。"},{id:8,question:"距离灵山景区多远？",answer:"距灵山胜境景区入口约1-3公里，车程5-10分钟；步行约15-20分钟，沿路风景优美。"},{id:9,question:"可以打包外带吗？",answer:"支持打包外带，提供环保餐盒；部分热菜建议堂食口感更佳，外带可能影响风味。"}],a=[{id:0,question:"民宿一晚价格多少，有无淡旺季差价？",answer:"标准间平日价格200-350元/晚，周末上浮约30%；五一、国庆等旺季价格翻倍，建议提前预订锁定价格。"},{id:1,question:"民宿距离灵山景区车程多久？",answer:"距灵山胜境景区约5-15分钟车程，步行约20-30分钟；部分民宿提供免费接送服务，预订时可咨询。"},{id:2,question:"房间包含早餐吗？",answer:"部分房型含双早，具体以预订页面为准；不含早的房型可加购早餐，人均30-50元，提供中式和西式两种选择。"},{id:3,question:"入住、退房时间规定？",answer:"入住时间为14:00后，退房时间为12:00前；如需延迟退房请联系前台，视房态可能免费延至14:00。"},{id:4,question:"可以携带宠物入住吗？",answer:"部分房型允许携带小型宠物（10kg以下），需提前告知并缴纳清洁费50元；大型宠物建议咨询宠物友好型民宿。"},{id:5,question:"民宿有没有停车场？",answer:"民宿提供免费停车位，先到先得；车位不足时可在周边公共停车场停放，步行约3分钟。"},{id:6,question:"房间有无独立卫浴？",answer:"所有房型均配备独立卫浴，24小时热水供应；部分高级房型配备浴缸，可在预订时选择。"},{id:7,question:"有没有双人/家庭套房？",answer:"提供大床房、双床房及家庭套房（1大床+1小床），家庭套房适合3-4人入住，面积宽敞舒适。"},{id:8,question:"民宿周边吃饭方便吗？",answer:"民宿周边500米内有多家餐馆和便利店，步行5分钟可达；前台可推荐附近特色美食，部分民宿提供管家服务。"},{id:9,question:"能否开具住宿发票？",answer:"可开具增值税普通发票或专用发票，退房时告知前台即可；如需专票请提前提供企业开票信息。"}];function u(i){const t=e([]),a=e(-1),u=e(!1);let o=null,r=3;const d=()=>{u.value=!0,setTimeout(()=>{const e=t.value[0],n=i.filter(n=>n.id!==e.id),s=r%n.length,o=(r+1)%n.length;r+=2,t.value=[e,n[s],n[o]],a.value=-1,u.value=!1},200)};return n(()=>{t.value=i.slice(0,3),a.value=-1,o=setInterval(d,6e4)}),s(()=>{o&&(clearInterval(o),o=null)}),{displayed:t,expandedId:a,fading:u,toggleExpand:e=>{a.value=a.value===e?-1:e}}}const o=[{id:0,question:"灵山景区门票多少钱，老人学生有优惠吗？",answer:"成人票210元/人，儿童1.2米以下免票，1.2-1.5米半价；65岁以上老人凭身份证半价；学生凭学生证享8折优惠；团体10人以上可享团体票。"},{id:1,question:"灵山大佛开放和闭园时间是几点？",answer:"灵山胜境景区开放时间为 07:30-17:30（夏季可能延长至18:00），建议上午前往光线最佳，闭园前1小时停止入园。"},{id:2,question:"灵山停车场收费标准，有没有免费车位？",answer:"小型车辆10元/次（当日有效），大型车辆20元/次；停车场位于景区入口两侧，节假日车位紧张建议早到；景区周边部分酒店住客可享免费停车。"},{id:3,question:"完整游览灵山景区大概需要多久？",answer:"全程步行游览约需4-5小时，乘坐观光车约3小时；建议预留半天时间，重点游览灵山大佛、九龙灌浴、灵山梵宫等核心景点。"},{id:4,question:"灵山周边好吃的农家菜饭店推荐？",answer:"灵山周边推荐：灵山小镇拈花湾内的素斋餐厅、马山农家乐聚集区的太湖三白馆、以及景区出口处的灵山食府，人均60-120元不等。"},{id:5,question:"灵山附近平价高性价比民宿有哪些？",answer:"灵山附近平价民宿推荐：灵山小镇民宿（150-300元/晚）、太湖边精品客栈（200-400元/晚）、马山村民宿（100-200元/晚），建议提前平台预订。"},{id:6,question:"带老人小孩游玩灵山省力路线怎么规划？",answer:"推荐乘坐观光车游览：入口 → 阿育王柱 → 灵山大佛（抱佛脚） → 九龙灌浴（整点表演） → 灵山梵宫 → 五印坛城，全程约3小时，步行较少。"},{id:7,question:"景区观光车怎么收费，有哪些停靠站点？",answer:"观光车单程30元/人，通票50元/人（当日不限次数）；停靠站点：入口广场、阿育王柱、灵山大佛、九龙灌浴、灵山梵宫、五印坛城，覆盖全部核心景点。"},{id:8,question:"节假日灵山人流量大吗，需要错峰入园吗？",answer:"春节、五一、国庆等重大节假日人流量较大，建议错峰出行或上午9点前入园；平日游览体验更佳，拍照打卡无需排队。"},{id:9,question:"景区内素食餐厅人均价位怎么样？",answer:"灵山梵宫内有无自助素斋餐厅（人均80元），祥符禅寺附近有素面馆（人均30元），推荐使用灵山APP提前查看菜单并预订。"},{id:10,question:"灵山大佛祈福有什么礼仪和讲究？",answer:"灵山祈福建议顺时针绕佛三圈，双手合十虔诚礼拜；可在祥符禅寺请香祈福，在祈福普缘挂祈福牌；抱佛脚寓意好运，佛手前祈求平安吉祥。"},{id:11,question:"无锡市区到灵山怎么坐公交/地铁？",answer:"从无锡市区可乘坐地铁2号线至梅园站，换乘89路公交直达灵山胜境；或乘坐乐游2号线（旅游专线）直达景区，全程约1小时。"},{id:12,question:"进景区可以自带零食和饮用水吗？",answer:"可以自带零食和饮用水入园，景区内设有多个休息区和直饮水点；但请注意不要在殿堂内饮食，保持安静肃穆。"},{id:13,question:"适合多人聚餐的灵山周边饭店有哪些？",answer:"推荐灵山梵宫素斋大厅（可容纳100人同时就餐）、灵山食府包间（适合10-20人聚餐）、以及拈花湾小镇内的太湖渔家（主打太湖三白，适合家庭聚餐）。"},{id:14,question:"附近民宿能不能携带宠物入住？",answer:'部分民宿允许携带小型宠物（10kg以下），需提前告知并缴纳清洁费50元；推荐预订时筛选"宠物友好"标签的民宿。'},{id:15,question:"灵山哪个时间段拍照光线最好看？",answer:"上午8:00-10:00和下午15:30-17:00光线最柔和，适合拍照；灵山大佛正面朝南，上午拍摄逆光较少；九龙灌浴喷泉表演时（整点）拍摄效果最佳。"},{id:16,question:"景区有行李寄存处吗，收费多少钱？",answer:"景区入口处设有行李寄存处，小件行李免费寄存，大件行李收费10元/件（当日有效），开放时间与景区一致。"},{id:17,question:"周边饭店需要提前打电话预约吗？",answer:"周末及节假日建议提前1-2小时电话预约，平日通常无需预约；大桌聚餐（6人以上）建议提前预订，部分热门餐厅需提前1天预约。"},{id:18,question:"民宿标准入住、退房时间是几点？",answer:"入住时间为14:00后，退房时间为12:00前；如需延迟退房请联系前台，视房态可能免费延至14:00，部分民宿收取半天房费。"},{id:19,question:"灵山大佛高度多少，建造历史介绍？",answer:'灵山大佛高88米（含莲花座），由1560块青铜壁板拼装而成，1997年落成，是中国五方五佛之东方大佛，右手"施无畏印"代表除却痛苦，左手"与愿印"代表给予快乐。'},{id:20,question:"下雨天去灵山游玩体验好不好？",answer:"下雨天景区人少，氛围更清幽，但部分户外项目体验受限；建议携带雨具，灵山梵宫等室内景点不受天气影响，雨中游览别有一番意境。"},{id:21,question:"景区人工讲解、电子讲解怎么收费？",answer:"人工讲解服务200元/批次（1-10人），电子讲解器租赁20元/台（押金200元），灵山APP提供免费语音讲解，推荐提前下载离线包。"},{id:22,question:"灵山周边饭店招牌特色菜品是什么？",answer:"周边饭店招牌菜：灵山素斋（香菇面筋、素蟹黄）、太湖三白（白鱼、白虾、银鱼）、无锡小笼包、酱排骨，均为当地特色美食。"},{id:23,question:"预订民宿是否包含免费早餐？",answer:"部分房型含双早，具体以预订页面为准；不含早的房型可加购早餐，人均30-50元，提供中式和西式两种选择，儿童早餐享半价优惠。"},{id:24,question:"灵山避人流游玩路线攻略？",answer:"避人流路线：从入口左侧步道直达灵山梵宫（开园时人少） → 五印坛城 → 曼飞龙塔 → 午餐后前往九龙灌浴（避开整点表演高峰） → 最后参观灵山大佛，全程人少体验佳。"},{id:25,question:"景区周边餐饮人均消费大概多少？",answer:"灵山周边餐饮人均消费约60-120元，素斋餐厅人均80-100元，农家乐约50-80元/人，太湖三白等特色菜价格稍高，建议根据预算选择。"},{id:26,question:"哪家民宿可以开具正规住宿发票？",answer:"灵山小镇内正规民宿均可开具增值税普通发票，部分支持专用发票；预订时请在订单备注中注明开票需求，退房时向前台提供开票信息即可。"},{id:27,question:"景区内有无香火售卖，价格贵不贵？",answer:"祥符禅寺内设香火流通处，普通线香10-20元/把，祈福香50-100元不等；景区提倡文明敬香，建议随缘请购，不在校外购买高价香。"},{id:28,question:"距离灵山10分钟车程内住宿推荐？",answer:"灵山小镇拈花湾内有多家精品客栈（步行5分钟入园），马山镇上平价民宿（车程8分钟），太湖边度假酒店（车程10分钟，部分房型可观湖景）。"},{id:29,question:"景区内有无遮阳休息的座椅区域？",answer:"景区内设有多个遮阳休息区和木质座椅，主要分布在灵山梵宫广场、九龙灌浴观景台、五印坛城庭院；夏季建议携带遮阳帽和防晒用品。"}];function r(){const i=e([]),t=e(!1);let a=null;const u=(e,n)=>{const s=[...e];for(let i=s.length-1;i>0;i--){const e=Math.floor(Math.random()*(i+1));[s[i],s[e]]=[s[e],s[i]]}return s.slice(0,n)},r=()=>{t.value=!0,setTimeout(()=>{const e=i.value[0],n=i.value[1],s=o.map(e=>e.question).filter(s=>s!==e&&s!==n),a=u(s,4);i.value=[e,n,...a],t.value=!1},200)};return n(()=>{(()=>{const e=o.map(e=>e.question).slice(2);i.value=[o[0].question,o[1].question,...u(e,4)]})(),a=setInterval(r,6e4)}),s(()=>{a&&(clearInterval(a),a=null)}),{displayed:i,fading:t}}export{r as a,t as f,a as h,i as s,u};
